CREATE DATAFLOW "modular_orders_a" FROM QUEUE "modular_requests_a" AS "__t$1_order_item" WHERE ( ( "__t$1_order_item" . AMOUNT ) > 0 AND ( "__t$1_order_item" . AMOUNT ) <= 1000000 ) AS BEGIN BEGIN ATOMIC LET "__t$2_target" = "__t$1_order_item" . ACCOUNT_ID ; LET "__t$3_amount" = "__t$1_order_item" . AMOUNT ; LET "__t$4_account" = SELECT ID , ACTIVE , TIER , CREDIT_LIMIT FROM "modular_accounts_a" WHERE ID = "__t$2_target" ; REQUIRE "__t$4_account" IS NOT NULL AND "__t$4_account" . ID = ( ( "__t$2_target" ) ) ELSE 'MissingAccount' ; REQUIRE "__t$4_account" . ACTIVE ELSE 'InactiveAccount' ; LET "__t$5_tier" = "__t$4_account" . TIER ; REQUIRE "__t$5_tier" = 'gold' OR "__t$5_tier" = 'standard' ELSE 'UnsupportedTier' ; REQUIRE "__t$3_amount" <= "__t$4_account" . CREDIT_LIMIT ELSE 'CreditLimitExceeded' ; LET "__t$6_summary" = 'caller-local-shadow-sentinel' ; LET "__t$7_token" = RANDOM_TOKEN ( 16 ) ; REQUIRE ( "__t$7_token" = "__t$7_token" ) ELSE 'ImpureTokenMismatch' ; LET "__t$9_order_id" = "__t$1_order_item" . ID ; LET "__t$10_account_id" = "__t$1_order_item" . ACCOUNT_ID ; LET "__t$11_amount" = "__t$1_order_item" . AMOUNT ; LET "__t$12_note" = "__t$1_order_item" . NOTE ; LET "__t$13_summary" = ( ( CASE WHEN ( ( "__t$11_amount" ) ) >= 1000 THEN 'large' ELSE CASE WHEN ( ( "__t$11_amount" ) ) >= 100 THEN 'medium' ELSE 'small' END END ) || ':' || ( CASE WHEN ( ( "__t$11_amount" ) ) >= 1000 AND ( CASE WHEN ( ( ( "__t$12_note" ) ) ) = '' THEN 'empty' ELSE CASE WHEN ( ( ( "__t$12_note" ) ) ) = 'priority' THEN 'priority-note' ELSE ( ( ( "__t$12_note" ) ) ) END END ) = 'empty' THEN 'review' ELSE CASE WHEN ( ( "__t$11_amount" ) ) >= 1000 THEN 'elevated' ELSE CASE WHEN ( CASE WHEN ( ( ( "__t$12_note" ) ) ) = '' THEN 'empty' ELSE CASE WHEN ( ( ( "__t$12_note" ) ) ) = 'priority' THEN 'priority-note' ELSE ( ( ( "__t$12_note" ) ) ) END END ) = 'priority-note' THEN 'expedited' ELSE 'routine' END END END ) || ':' || ( CASE WHEN ( ( "__t$12_note" ) ) = '' THEN 'empty' ELSE CASE WHEN ( ( "__t$12_note" ) ) = 'priority' THEN 'priority-note' ELSE ( ( "__t$12_note" ) ) END END ) || ':' || ( ( CASE WHEN ( ( ( "__t$11_amount" ) ) ) >= 1000 THEN 'window=institutional-clearance-corridor-v1/band=large/ledger-policy=primary-verified-settlement-lane-alpha-01' ELSE CASE WHEN ( ( ( "__t$11_amount" ) ) ) >= 100 THEN 'window=commercial-clearance-corridor-v1/band=medium/ledger-policy=standard-verified-settlement-lane-beta-02' ELSE 'window=retail-micro-clearance-corridor-v1/band=small/ledger-policy=automated-verified-settlement-lane-gamma-03' END END ) || '|' || ( CASE WHEN ( ( ( "__t$11_amount" ) ) ) >= 1000 THEN 'schedule=tier-alpha/corridor=priority-wire-settlement-profile-v1/settlement-class=institutional-high-value-order' ELSE CASE WHEN ( ( ( "__t$11_amount" ) ) ) >= 250 THEN 'schedule=tier-beta/corridor=standard-commercial-settlement-profile-v1/settlement-class=commercial-mid-value-order' ELSE 'schedule=tier-gamma/corridor=economy-batch-settlement-profile-v1/settlement-class=automated-low-value-order-lane' END END ) || '|' || ( CASE WHEN ( ( ( "__t$11_amount" ) ) ) >= 1000 THEN 'compliance=dual-control-ledger-stream-followup-atomic-v1/hygiene=lexical-frame-isolated/audit-band=institutional' ELSE CASE WHEN ( ( ( "__t$11_amount" ) ) ) >= 100 THEN 'compliance=verified-account-tier-credit-guard-atomic-v1/hygiene=lexical-frame-isolated/audit-band=commercial-std' ELSE 'compliance=automated-account-guard-atomic-settlement-v1/hygiene=lexical-frame-isolated/audit-band=retail-standard' END END ) ) ) ; INSERT INTO "modular_ledger_a" VALUES ( ( ( "__t$9_order_id" ) ) , ( ( "__t$10_account_id" ) ) , "__t$11_amount" , "__t$13_summary" ) ON CONFLICT ( ID ) DO ASSERT SAME ROW ; LET "__t$14_order_id" = ( ( "__t$9_order_id" ) ) ; LET "__t$15_account_id" = ( ( "__t$10_account_id" ) ) ; LET "__t$16_summary" = "__t$13_summary" ; PRODUCE INTO "modular_events_a" VALUES ( ( ( "__t$14_order_id" ) ) , ( ( "__t$15_account_id" ) ) , "__t$16_summary" ) ; ENQUEUE INTO "modular_followup_a" VALUES ( ( ( "__t$14_order_id" ) ) , ( ( "__t$15_account_id" ) ) , "__t$16_summary" ) ; LET "__t$8_ret" = ( ( "__t$9_order_id" ) ) ; LET "__t$17_settled" = "__t$8_ret" ; REQUIRE "__t$17_settled" = "__t$1_order_item" . ID ELSE 'WrongReturnedOrder' ; REQUIRE "__t$6_summary" = 'caller-local-shadow-sentinel' AND "__t$1_order_item" . NOTE <> 'rollback_after_call' ELSE 'PostCallRejected' ; END ; END;
AUTHORIZE DATAFLOW "modular_orders_a" AS ROLE CURRENT_ROLE;
ACTIVATE DATAFLOW "modular_orders_a";
