CREATE DATAFLOW "modular_dispatch_a" FROM QUEUE "modular_followup_a" AS "__t$1_queued" AS BEGIN BEGIN ATOMIC INSERT INTO "modular_dispatched_a" VALUES ( ( ( "__t$1_queued" . ID ) ) , ( ( "__t$1_queued" . ACCOUNT_ID ) ) , "__t$1_queued" . SUMMARY ) ON CONFLICT ( ID ) DO ASSERT SAME ROW ; END ; END;
AUTHORIZE DATAFLOW "modular_dispatch_a" AS ROLE CURRENT_ROLE;
ACTIVATE DATAFLOW "modular_dispatch_a";
